class BankAccount
{
    private int acctNum;
    private double balance;
    public BankAccount(int num, double bal)
    {
        acctNum = num;
        balance = bal;
    }
    @Override
    public boolean equals(Object obj)
    {
        boolean result;
        if(obj == this)
            result = true;
        else if(obj == null)
            result = false;
        else if(obj.getClass() != this.getClass())
            result = false;
        BankAccount secondAcct = (BankAccount)obj;
        if(acctNum == secondAcct.acctNum
            && balance == secondAcct.balance)
            result = true;
        else
            result = false;
        return result;
    }
}

